23	    required Uint8List bytes,
24	    required ExportFormat format,
25	  }) async {
26	    try {
27	      final dir = await getTemporaryDirectory();
28	      final extension = format == ExportFormat.pdf ? 'pdf' : 'json';
29	      final name = format == ExportFormat.pdf ? 'cerne-resumo' : 'cerne-dados';
30	      final file = File('${dir.path}/$name.$extension');
31	      await file.writeAsBytes(bytes, flush: true);
32	      await SharePlatform.instance.share(ShareParams(files: [XFile(file.path)]));
33	      return const Right(unit);
34	    } catch (_) {
35	      return const Left(
36	        NetworkTimeoutFailure(message: 'Falha ao salvar/compartilhar o arquivo.', requestId: ''),
37	      );
