import 'dart:async';

import 'package:cerne/core/di/service_locator.dart';
import 'package:cerne/features/export/presentation/bloc/export_bloc.dart';
import 'package:cerne/features/export/presentation/bloc/export_event.dart';
import 'package:cerne/features/export/presentation/bloc/export_state.dart';
import 'package:cerne/features/export/presentation/widgets/export_concluded_view.dart';
import 'package:cerne/features/export/presentation/widgets/export_empty_period_view.dart';
import 'package:cerne/features/export/presentation/widgets/export_failed_view.dart';
import 'package:cerne/features/export/presentation/widgets/export_narrative_failed_view.dart';
import 'package:cerne/features/export/presentation/widgets/export_pending_view.dart';
import 'package:cerne/features/export/presentation/widgets/export_processing_view.dart';
import 'package:cerne/features/session/presentation/bloc/session_bloc.dart';
import 'package:cerne/features/session/presentation/bloc/session_event.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// The `StatefulWidget` `showModalBottomSheet` builds from "Meus
/// Registros"' download icon (data-model.md, research.md R7/R8,
/// contracts/export-bloc.md). Exhaustively switches on `ExportState`'s six
/// variants from the moment it compiles.
class ExportSheet extends StatefulWidget {
  const ExportSheet({super.key, required this.periodStart, required this.periodEnd});

  final DateTime? periodStart;
  final DateTime? periodEnd;

  @override
  State<ExportSheet> createState() => _ExportSheetState();
}

class _ExportSheetState extends State<ExportSheet> {
  late final ExportBloc _bloc;
  late final StreamSubscription<void> _reauthSubscription;

  @override
  void initState() {
    super.initState();
    _bloc = getIt<ExportBloc>()..add(ExportRequested(widget.periodStart, widget.periodEnd));
    _reauthSubscription = _bloc.reauthRequired.listen((_) {
      if (!mounted) return;
      context.read<SessionBloc>().add(const AuthExpiredDetected());
    });
  }

  @override
  void dispose() {
    _reauthSubscription.cancel();
    _bloc.close();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return BlocProvider<ExportBloc>.value(
      value: _bloc,
      child: SafeArea(
        child: BlocBuilder<ExportBloc, ExportState>(
          builder: (context, state) => switch (state) {
            ExportPending() => ExportPendingView(onClosePressed: () => _close(context)),
            ExportProcessing() => ExportProcessingView(onClosePressed: () => _close(context)),
            ExportConcluded() => ExportConcludedView(
              isDownloadingPdf: state.isDownloadingPdf,
              isDownloadingRaw: state.isDownloadingRaw,
              pdfDownloadFailure: state.pdfDownloadFailure,
              rawDownloadFailure: state.rawDownloadFailure,
              onPdfDownloadPressed: () =>
                  context.read<ExportBloc>().add(const PdfDownloadRequested()),
              onRawDataDownloadPressed: () =>
                  context.read<ExportBloc>().add(const RawDataDownloadRequested()),
              onClosePressed: () => _close(context),
            ),
            ExportNarrativeFailed() => ExportNarrativeFailedView(
              isDownloadingRaw: state.isDownloadingRaw,
              rawDownloadFailure: state.rawDownloadFailure,
              onRawDataDownloadPressed: () =>
                  context.read<ExportBloc>().add(const RawDataDownloadRequested()),
              onClosePressed: () => _close(context),
            ),
            ExportFailed() => ExportFailedView(onClosePressed: () => _close(context)),
            ExportEmptyPeriod() => ExportEmptyPeriodView(onClosePressed: () => _close(context)),
          },
        ),
      ),
    );
  }

  void _close(BuildContext context) => Navigator.of(context).pop();
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:flutter/material.dart';

/// FR-005/FR-008/FR-009/FR-010/FR-011.
class ExportConcludedView extends StatelessWidget {
  const ExportConcludedView({
    super.key,
    required this.isDownloadingPdf,
    required this.isDownloadingRaw,
    required this.pdfDownloadFailure,
    required this.rawDownloadFailure,
    required this.onPdfDownloadPressed,
    required this.onRawDataDownloadPressed,
    required this.onClosePressed,
  });

  final bool isDownloadingPdf;
  final bool isDownloadingRaw;
  final Failure? pdfDownloadFailure;
  final Failure? rawDownloadFailure;
  final VoidCallback onPdfDownloadPressed;
  final VoidCallback onRawDataDownloadPressed;
  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(
            Icons.check_circle,
            size: DesignTokens.spacing2xl,
            color: DesignTokens.colorSuccess,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          const Text('Resumo pronto', style: DesignTokens.textTitleSm),
          const SizedBox(height: DesignTokens.spacingLg),
          SizedBox(
            width: double.infinity,
            child: ElevatedButton(
              onPressed: isDownloadingPdf ? null : onPdfDownloadPressed,
              child: const Text('Baixar PDF'),
            ),
          ),
          if (pdfDownloadFailure != null)
            Padding(
              padding: const EdgeInsets.only(top: DesignTokens.spacingSm),
              child: ExportDownloadRetryBanner(
                message: pdfDownloadFailure!.message,
                onRetry: onPdfDownloadPressed,
              ),
            ),
          const SizedBox(height: DesignTokens.spacingSm),
          SizedBox(
            width: double.infinity,
            child: OutlinedButton(
              onPressed: isDownloadingRaw ? null : onRawDataDownloadPressed,
              child: const Text('Baixar dados brutos'),
            ),
          ),
          if (rawDownloadFailure != null)
            Padding(
              padding: const EdgeInsets.only(top: DesignTokens.spacingSm),
              child: ExportDownloadRetryBanner(
                message: rawDownloadFailure!.message,
                onRetry: onRawDataDownloadPressed,
              ),
            ),
          const SizedBox(height: DesignTokens.spacingMd),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

/// The shared inline retry affordance both `ExportConcludedView` and
/// `export_narrative_failed_view.dart` show below a failed download button
/// — same shape `records_page.dart`'s own private `_RetryBanner` already
/// established, defined here (rather than importing that file's private
/// class) so both export views can reuse one definition.
class ExportDownloadRetryBanner extends StatelessWidget {
  const ExportDownloadRetryBanner({super.key, required this.message, required this.onRetry});

  final String message;
  final VoidCallback onRetry;

  @override
  Widget build(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        Flexible(
          child: Text(message, style: DesignTokens.textBodyMd, textAlign: TextAlign.center),
        ),
        const SizedBox(width: DesignTokens.spacingSm),
        TextButton(onPressed: onRetry, child: const Text('Tentar novamente')),
      ],
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/network/failure.dart';
import 'package:cerne/features/export/presentation/widgets/export_concluded_view.dart';
import 'package:flutter/material.dart';

/// FR-006/FR-009/FR-010 — the AI summary failed but the underlying data is
/// still available; exactly one download control, no "Baixar PDF".
class ExportNarrativeFailedView extends StatelessWidget {
  const ExportNarrativeFailedView({
    super.key,
    required this.isDownloadingRaw,
    required this.rawDownloadFailure,
    required this.onRawDataDownloadPressed,
    required this.onClosePressed,
  });

  final bool isDownloadingRaw;
  final Failure? rawDownloadFailure;
  final VoidCallback onRawDataDownloadPressed;
  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(
            Icons.warning_amber,
            size: DesignTokens.spacing2xl,
            color: DesignTokens.colorError,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          const Text(
            'Não foi possível gerar o resumo com IA, mas seus dados estão '
            'disponíveis para download.',
            style: DesignTokens.textBodyLg,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingLg),
          SizedBox(
            width: double.infinity,
            child: OutlinedButton(
              onPressed: isDownloadingRaw ? null : onRawDataDownloadPressed,
              child: const Text('Baixar dados brutos'),
            ),
          ),
          if (rawDownloadFailure != null)
            Padding(
              padding: const EdgeInsets.only(top: DesignTokens.spacingSm),
              child: ExportDownloadRetryBanner(
                message: rawDownloadFailure!.message,
                onRetry: onRawDataDownloadPressed,
              ),
            ),
          const SizedBox(height: DesignTokens.spacingMd),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// FR-007 / the resolved Clarification — the generic, job-independent
/// failure state: shown the same way regardless of the backend's specific
/// error code, no download control of any kind. Its copy is deliberately
/// distinct from `export_narrative_failed_view.dart`'s.
class ExportFailedView extends StatelessWidget {
  const ExportFailedView({super.key, required this.onClosePressed});

  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(
            Icons.error_outline,
            size: DesignTokens.spacing2xl,
            color: DesignTokens.colorError,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          const Text(
            'Não foi possível gerar a exportação. Nenhum dado foi produzido.',
            style: DesignTokens.textBodyLg,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingLg),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// FR-003 — reached immediately from `create()`'s own `EXPORT_EMPTY_PERIOD`
/// failure; the sheet never shows "Pendente"/"Processando" first.
class ExportEmptyPeriodView extends StatelessWidget {
  const ExportEmptyPeriodView({super.key, required this.onClosePressed});

  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Icon(
            Icons.inbox_outlined,
            size: DesignTokens.spacing2xl,
            color: DesignTokens.colorTextSecondary,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          const Text(
            'Nenhum registro nesse período.',
            style: DesignTokens.textTitleSm,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingSm),
          const Text(
            'Ajuste o filtro de período em "Meus Registros" e tente novamente.',
            style: DesignTokens.textBodyMd,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingLg),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// FR-004/FR-010 — shown the instant the download icon is tapped, before
/// the `POST` even resolves.
class ExportPendingView extends StatelessWidget {
  const ExportPendingView({super.key, required this.onClosePressed});

  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const CircularProgressIndicator(color: DesignTokens.colorAccent),
          const SizedBox(height: DesignTokens.spacingMd),
          const Text(
            'Preparando exportação...',
            style: DesignTokens.textTitleSm,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

import 'package:cerne/core/design_tokens.dart';
import 'package:flutter/material.dart';

/// FR-004/FR-010 — an indeterminate bar, since the backend never reports a
/// percentage (research.md R3).
class ExportProcessingView extends StatelessWidget {
  const ExportProcessingView({super.key, required this.onClosePressed});

  final VoidCallback onClosePressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.all(DesignTokens.spacingLg),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          const Text(
            'Gerando resumo com IA...',
            style: DesignTokens.textTitleSm,
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: DesignTokens.spacingMd),
          const LinearProgressIndicator(color: DesignTokens.colorAccent),
          const SizedBox(height: DesignTokens.spacingMd),
          TextButton(onPressed: onClosePressed, child: const Text('Fechar')),
        ],
      ),
    );
  }
}

