    exportRepository = MockExportRepository();
    exportFileRepository = MockExportFileRepository();
    // create() never resolves — this test only needs ExportSheet to
    // construct and mount successfully with the right constructor args; it
    // never needs the export flow to actually complete.
    when(
      () => exportRepository.create(
        periodStart: any(named: 'periodStart'),
        periodEnd: any(named: 'periodEnd'),
      ),
    ).thenAnswer((_) => Completer<Either<Failure, String>>().future);

    if (getIt.isRegistered<ExportBloc>()) getIt.unregister<ExportBloc>();
    getIt.registerFactory<ExportBloc>(
      () => ExportBloc(exportRepository: exportRepository, exportFileRepository: exportFileRepository),
    );
  });

  tearDown(() {
    if (getIt.isRegistered<ExportBloc>()) getIt.unregister<ExportBloc>();
  });

  Future<void> pumpRecordsPage(WidgetTester tester, RecordsState state) async {
    whenListen(recordsBloc, Stream.value(state), initialState: state);
    await tester.pumpWidget(
      MaterialApp(
        home: BlocProvider<RecordsBloc>.value(value: recordsBloc, child: const RecordsPage()),
      ),
    );
    await tester.pump();
  }

  testWidgets(
    '1: thisWeek -> ExportSheet constructed with periodEnd: null and '
    'periodStart equal to this week\'s most-recent-Monday boundary',
    (tester) async {
      await pumpRecordsPage(
        tester,
        RecordsLoaded(
          entries: [_buildEntry(id: 'e1')],
          nextCursor: null,
          isLoadingMore: false,
          dateRange: DateRangeOption.thisWeek,
        ),
      );

      await tester.tap(find.byIcon(Icons.download_outlined));
      await tester.pump();

      final expectedBounds = DateRangeOption.thisWeek.boundsAt(DateTime.now());
      final sheet = tester.widget<ExportSheet>(find.byType(ExportSheet));
      expect(sheet.periodStart, expectedBounds.from);
      expect(sheet.periodEnd, isNull);
    },
  );

  testWidgets(
    '2: allTime -> ExportSheet constructed with periodStart: null, periodEnd: null',
    (tester) async {
      await pumpRecordsPage(
        tester,
        RecordsLoaded(entries: [_buildEntry(id: 'e1')], nextCursor: null, isLoadingMore: false),
      );

      await tester.tap(find.byIcon(Icons.download_outlined));
      await tester.pump();

      final sheet = tester.widget<ExportSheet>(find.byType(ExportSheet));
      expect(sheet.periodStart, isNull);
      expect(sheet.periodEnd, isNull);
    },
  );

  testWidgets(
    '3: a rapid double-tap on the download icon calls showModalBottomSheet exactly once',
    (tester) async {
      await pumpRecordsPage(
        tester,
        RecordsLoaded(entries: [_buildEntry(id: 'e1')], nextCursor: null, isLoadingMore: false),
      );

      await tester.tap(find.byIcon(Icons.download_outlined));
      // The second tap lands on the modal barrier the first tap's sheet is
      // already raising — exactly the guarded no-op FR-011 requires.
      await tester.tap(find.byIcon(Icons.download_outlined), warnIfMissed: false);
      await tester.pump();

      expect(find.byType(ExportSheet), findsOneWidget);
    },
  );

  testWidgets('4: sheet dismissed, download icon tapped again -> a fresh sheet opens', (
    tester,
  ) async {
    await pumpRecordsPage(
      tester,
      RecordsLoaded(entries: [_buildEntry(id: 'e1')], nextCursor: null, isLoadingMore: false),
    );

    await tester.tap(find.byIcon(Icons.download_outlined));
    await tester.pump();
    expect(find.byType(ExportSheet), findsOneWidget);

    // Dismiss programmatically rather than tapping "Fechar" directly: the
    // sheet's entrance animation and ExportPendingView's own indeterminate
    // spinner (which animates forever) make tap-position-based interaction
    // on the sheet's content unreliable in a widget test.
    Navigator.of(tester.element(find.byType(ExportSheet))).pop();
    await tester.pump(const Duration(milliseconds: 300));
    expect(find.byType(ExportSheet), findsNothing);

    await tester.tap(find.byIcon(Icons.download_outlined));
    await tester.pump();
    expect(find.byType(ExportSheet), findsOneWidget);
  });

  testWidgets(
    '5: opening/closing the export sheet leaves RecordsBloc\'s own state untouched',
    (tester) async {
      final seeded = RecordsLoaded(
        entries: [_buildEntry(id: 'e1')],
        nextCursor: null,
        isLoadingMore: false,
      );
      await pumpRecordsPage(tester, seeded);

      await tester.tap(find.byIcon(Icons.download_outlined));
      await tester.pump();
      Navigator.of(tester.element(find.byType(ExportSheet))).pop();
      await tester.pump(const Duration(milliseconds: 300));

      verifyNever(() => recordsBloc.add(any()));
      expect(recordsBloc.state, seeded);
    },
  );
}

# Contract: Records header's download icon (`lib/features/records/presentation/pages/records_page.dart`)

Extends `_Header`/`_RecordsPageState` in place (FR-001/FR-002/FR-011). `RecordsBloc`/`RecordsEvent`/
`RecordsState` are unchanged — no new event, no new field (research.md R8).

```dart
class _Header extends StatelessWidget {
  const _Header({required this.onExportPressed});
  final VoidCallback onExportPressed;

  @override
  Widget build(BuildContext context) {
    return Padding(
      // ...unchanged back-arrow + title...
      child: Row(
        children: [
          /* back arrow, title — unchanged */
          IconButton(
            onPressed: onExportPressed,                              // was: () {} (inert placeholder)
            icon: const Icon(Icons.download_outlined, color: DesignTokens.colorTextPrimary),
          ),
        ],
      ),
    );
  }
}
```

```dart
class _RecordsPageState extends State<RecordsPage> {
  bool _isOpeningExportSheet = false;   // NEW

  Future<void> _openExportSheet(BuildContext context) async {
    if (_isOpeningExportSheet) return;                                   // FR-011
    _isOpeningExportSheet = true;
    final state = context.read<RecordsBloc>().state;
    final dateRange = state is RecordsLoaded ? state.dateRange : DateRangeOption.allTime;
    final bounds = dateRange.boundsAt(DateTime.now());                    // RF06's own pure extension, reused
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      builder: (_) => ExportSheet(periodStart: bounds.from, periodEnd: bounds.to),
    );
    if (mounted) _isOpeningExportSheet = false;
  }

  // build(): `_Header(onExportPressed: () => _openExportSheet(context))` replaces the bare `_Header()`.
}
```

- `_isOpeningExportSheet` resets to `false` only after `showModalBottomSheet`'s `Future` resolves (the sheet
  was dismissed) and only if the widget is still mounted — a second tap while the sheet is open is already
  physically blocked by the modal barrier Flutter itself draws, so this flag's only real job is absorbing a
  double-tap in the brief window before the sheet has finished animating in.
- No change to `RecordsBloc`'s own filter state: reading `context.read<RecordsBloc>().state` here is a
  one-time snapshot at tap time, never a `watch` — `_Header` itself stays a plain, non-rebuilding
  `StatelessWidget` with respect to `RecordsBloc` (unaffected by RF05, same as `_SearchBar`'s existing
  `context.watch<RecordsBloc>()` usage for the filter icon's own highlight state, which this unit does not
  touch).

## Test scenarios this contract owns

| # | Scenario | Expected |
|---|---|---|
| 1 | `RecordsLoaded(dateRange: DateRangeOption.thisWeek)`, download icon tapped | `ExportSheet` is constructed with `periodStart` = this week's most-recent-Monday boundary, `periodEnd: null` |
| 2 | `RecordsLoaded(dateRange: DateRangeOption.allTime)`, download icon tapped | `ExportSheet` is constructed with `periodStart: null, periodEnd: null` |
| 3 | Download icon tapped twice in rapid succession (before the first `showModalBottomSheet` future resolves) | `showModalBottomSheet` is called exactly once |
| 4 | Sheet dismissed, download icon tapped again | `showModalBottomSheet` is called again (a fresh `ExportSheet`/`ExportBloc`, research.md R6) — not blocked by the now-`false` guard |
| 5 | Opening/closing the export sheet, at any of its states | `RecordsBloc`'s own state (`entries`, `dateRange`, scroll position via `ScrollController`) is bit-for-bit unchanged before and after (FR-010/SC-004) |

